CREATE FUNCTION public.bestelbot_advies_loggen(p_vestiging text,p_datum date,p_leverdag date,p_regels jsonb,p_methode_versie text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;r jsonb;a public.bestel_advies;g jsonb;n int:=0;
BEGIN IF NOT public.is_service_call() THEN RAISE EXCEPTION 'Alleen service role' USING ERRCODE='42501';END IF;
IF p_methode_versie IS NOT NULL AND (length(p_methode_versie)>100 OR trim(p_methode_versie)='') THEN RAISE EXCEPTION 'Ongeldige methode_versie';END IF;
FOR r IN SELECT * FROM jsonb_array_elements(p_regels) LOOP g:=coalesce(r->'gegevens','{}');
IF jsonb_typeof(g)<>'object' THEN RAISE EXCEPTION 'gegevens moet een object zijn';END IF;
IF g ? 'voorraad_artikel_id' AND NOT EXISTS(SELECT 1 FROM public.voorraad_artikel WHERE id=(g->>'voorraad_artikel_id')::uuid AND vestiging=p_vestiging) THEN RAISE EXCEPTION 'Proefartikel andere vestiging';END IF;
IF g ? 'kassa_ids' THEN IF jsonb_typeof(g->'kassa_ids')<>'array' THEN RAISE EXCEPTION 'Ongeldige kassa_ids';END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(g->'kassa_ids')x WHERE nullif(x->>'id','') IS NULL OR jsonb_typeof(x->'per_eenheid') IS DISTINCT FROM 'number' OR (x->>'per_eenheid')::numeric<=0) OR (SELECT count(*) FROM jsonb_array_elements(g->'kassa_ids'))<>(SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(g->'kassa_ids')x) THEN RAISE EXCEPTION 'Ongeldige of dubbele kassafactor';END IF;END IF;
IF (g ? 'periode_van')<>(g ? 'periode_tot') OR (g ? 'periode_van' AND (g->>'periode_van')::date>(g->>'periode_tot')::date) THEN RAISE EXCEPTION 'Ongeldige periode';END IF;
IF g ? 'periode_van' AND (to_char((g->>'periode_van')::date,'YYYY-MM-DD')<>g->>'periode_van' OR to_char((g->>'periode_tot')::date,'YYYY-MM-DD')<>g->>'periode_tot') THEN RAISE EXCEPTION 'Ongeldige datum';END IF;
IF g ? 'verwacht_verbruik' AND jsonb_typeof(g->'verwacht_verbruik') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Ongeldig verwacht_verbruik';END IF;
END LOOP;
result:=public.bestelbot_advies_vervangen(p_vestiging,p_datum,p_leverdag,p_regels);
FOR r IN SELECT * FROM jsonb_array_elements(p_regels) LOOP g:=coalesce(r->'gegevens','{}');
SELECT * INTO a FROM public.bestel_advies WHERE vestiging=p_vestiging AND leverdag=p_leverdag AND artikel=trim(r->>'artikel') AND leverancier IS NOT DISTINCT FROM nullif(trim(r->>'leverancier'),'') LIMIT 1;
INSERT INTO public.advies_log(vestiging,datum,leverdag,artikel,artikel_id,voorraad_artikel_id,advies,eenheid,gegevens,methode_versie) VALUES(p_vestiging,p_datum,p_leverdag,a.artikel,a.artikel_id,(g->>'voorraad_artikel_id')::uuid,a.hoeveelheid,a.eenheid,g,p_methode_versie)
ON CONFLICT(vestiging,leverdag,artikel,methode_versie) DO UPDATE SET advies=excluded.advies,datum=excluded.datum,artikel_id=excluded.artikel_id,voorraad_artikel_id=excluded.voorraad_artikel_id,eenheid=excluded.eenheid,gegevens=excluded.gegevens,werkelijk_besteld=NULL,later_verkocht=NULL,later_geteld=NULL,afwijking=NULL,leerstatus='onvolledig',bijgewerkt_op=now();n:=n+1;END LOOP;
UPDATE public.advies_log l SET advies=CASE WHEN x.vergelijkbaar THEN x.som ELSE l.advies END,leerstatus=CASE WHEN x.vergelijkbaar THEN 'onvolledig' ELSE 'niet vergelijkbaar: leveranciers/eenheden' END,gegevens=CASE WHEN x.vergelijkbaar THEN l.gegevens ELSE l.gegevens||'{"niet_vergelijkbaar":true}'::jsonb END
FROM(SELECT trim(r->>'artikel') artikel,sum((r->>'hoeveelheid')::numeric) som,count(DISTINCT coalesce(r->>'eenheid',''))=1 AND count(DISTINCT coalesce(r->'gegevens','{}'))=1 vergelijkbaar FROM jsonb_array_elements(p_regels)r GROUP BY trim(r->>'artikel'))x WHERE l.vestiging=p_vestiging AND l.leverdag=p_leverdag AND l.methode_versie IS NOT DISTINCT FROM p_methode_versie AND l.artikel=x.artikel;
RETURN result||jsonb_build_object('gelogd',n);END $$;
REVOKE ALL ON FUNCTION public.bestelbot_advies_loggen(text,date,date,jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.bestelbot_advies_loggen(text,date,date,jsonb,text) TO service_role;
CREATE VIEW public.v_advies_nauwkeurigheid WITH(security_invoker=true) AS SELECT vestiging,artikel,artikel_id,count(*) FILTER(WHERE later_verkocht<>0 AND afwijking IS NOT NULL)n,avg(afwijking) FILTER(WHERE later_verkocht IS NOT NULL)gemiddelde_afwijking,100*avg(abs(afwijking)/abs(nullif(later_verkocht,0)))mape,count(*) FILTER(WHERE later_verkocht IS NULL OR afwijking IS NULL)niet_vergelijkbaar,count(*) FILTER(WHERE later_verkocht=0)nulverbruik FROM public.advies_log GROUP BY vestiging,artikel,artikel_id;
CREATE VIEW public.v_leer_voorstellen_open WITH(security_invoker=true) AS SELECT * FROM public.leer_voorstel WHERE status='open' ORDER BY bijgewerkt_op DESC;
GRANT SELECT ON public.v_advies_nauwkeurigheid,public.v_leer_voorstellen_open TO authenticated,service_role;
CREATE FUNCTION public.leercurve_bijwerken() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE l public.advies_log;a public.voorraad_artikel;t record;x record;k numeric;r numeric;c numeric;ok boolean;besteld numeric;geteld numeric;v numeric;
BEGIN IF NOT public.is_service_call() THEN RAISE EXCEPTION 'Alleen service role' USING ERRCODE='42501';END IF;
FOR l IN SELECT * FROM public.advies_log LOOP k:=NULL;geteld:=NULL;besteld:=NULL;
IF l.eenheid IS NOT NULL AND NOT coalesce((l.gegevens->>'niet_vergelijkbaar')::boolean,false) THEN
WITH bronnen AS(SELECT h.aantal,h.eenheid_ruw eenheid,h.verpakking_ruw vorm FROM public.bestel_historie_import h WHERE h.vestiging=l.vestiging AND h.besteldatum BETWEEN l.datum AND l.leverdag AND (h.artikel_id=l.artikel_id OR (h.artikel_id IS NULL AND public.bestelbot_normaliseer(h.artikel_naam_ruw)=public.bestelbot_normaliseer(l.artikel)))
UNION ALL SELECT b.aantal,b.eenheid,v.vorm FROM public.bestel_signalen b LEFT JOIN public.artikel_vormen v ON v.id=b.artikel_vorm_id AND v.vestiging=b.vestiging WHERE b.vestiging=l.vestiging AND b.status IN ('besteld','geleverd') AND (b.besteld_op AT TIME ZONE 'Europe/Amsterdam')::date BETWEEN l.datum AND l.leverdag AND (b.artikel_id=l.artikel_id OR (b.artikel_id IS NULL AND public.bestelbot_normaliseer(b.naam)=public.bestelbot_normaliseer(l.artikel))) AND NOT EXISTS(SELECT 1 FROM public.bestel_historie_import h WHERE h.vestiging=b.vestiging AND nullif(trim(b.bestelreferentie),'') IS NOT NULL AND nullif(trim(h.extern_ordernummer),'')=trim(b.bestelreferentie) AND h.leverancier_id=b.leverancier_id)),
q AS(SELECT CASE WHEN eenheid=l.eenheid THEN aantal WHEN eenheid='doos' AND l.eenheid='fles' AND vorm ~ '24[×x]' THEN aantal*24 WHEN eenheid='fles' AND l.eenheid='doos' AND EXISTS(SELECT 1 FROM public.artikel_vormen av WHERE av.artikel_id=l.artikel_id AND av.vestiging=l.vestiging AND av.vorm ~ '24[×x]') THEN aantal/24 ELSE NULL END aantal FROM bronnen)
SELECT CASE WHEN count(*)=0 THEN 0 WHEN bool_and(aantal IS NOT NULL) THEN sum(aantal) END INTO besteld FROM q;END IF;
IF l.methode_versie IS NOT NULL AND l.gegevens ? 'kassa_ids' AND jsonb_array_length(l.gegevens->'kassa_ids')>0 AND l.gegevens ? 'periode_van' AND l.gegevens ? 'periode_tot' AND (l.gegevens->>'periode_tot')::date<(now() AT TIME ZONE 'Europe/Amsterdam')::date AND NOT coalesce((l.gegevens->>'niet_vergelijkbaar')::boolean,false) THEN
SELECT CASE WHEN count(*)>0 THEN sum(d.aantal*(m->>'per_eenheid')::numeric) END INTO k FROM jsonb_array_elements(l.gegevens->'kassa_ids')m JOIN public.kassa_verkoop_dag d ON d.lightspeed_product_id=m->>'id' AND d.vestiging=l.vestiging AND d.datum BETWEEN (l.gegevens->>'periode_van')::date AND (l.gegevens->>'periode_tot')::date;
SELECT * INTO a FROM public.voorraad_artikel WHERE id=l.voorraad_artikel_id;IF a.tel_eenheid=l.eenheid THEN SELECT tt.totaal INTO geteld FROM public.voorraad_telling tt WHERE tt.voorraad_artikel_id=l.voorraad_artikel_id AND tt.betrouwbaar AND tt.datum BETWEEN (l.gegevens->>'periode_van')::date AND (l.gegevens->>'periode_tot')::date ORDER BY tt.geteld_op DESC,tt.id DESC LIMIT 1;END IF;END IF;
UPDATE public.advies_log SET werkelijk_besteld=besteld,later_verkocht=k,later_geteld=geteld,afwijking=CASE WHEN k IS NOT NULL THEN advies-k END,leerstatus=CASE WHEN k IS NULL THEN 'onvolledig' ELSE 'afgerond' END,bijgewerkt_op=now() WHERE id=l.id;END LOOP;
FOR a IN SELECT * FROM public.voorraad_artikel LOOP
FOR t IN SELECT tt.*,lead(id) OVER(ORDER BY geteld_op,id)eind_id,lead(datum) OVER(ORDER BY geteld_op,id)eind_datum,lead(moment) OVER(ORDER BY geteld_op,id)eind_moment,lead(totaal) OVER(ORDER BY geteld_op,id)eind_totaal FROM public.voorraad_telling tt WHERE tt.voorraad_artikel_id=a.id AND tt.betrouwbaar LOOP IF t.eind_id IS NULL THEN CONTINUE;END IF;
SELECT coalesce(sum(b.hoeveelheid) FILTER(WHERE soort='ontvangst'),0),coalesce(sum(b.hoeveelheid) FILTER(WHERE soort='correctie'),0),-coalesce(sum(b.hoeveelheid) FILTER(WHERE soort='kassa'),0),coalesce(bool_and(b.hoeveelheid IS NOT NULL AND b.bronkwaliteit NOT LIKE 'onvolledig%'),true) INTO r,c,k,ok FROM public.voorraad_bewegingen_lezen(a.vestiging)b WHERE b.voorraad_artikel_id=a.id AND b.datum>=public.voorraad_daggrens(t.datum,t.moment) AND b.datum<public.voorraad_daggrens(t.eind_datum,t.eind_moment);
ok:=ok AND t.moment=t.eind_moment AND public.voorraad_daggrens(t.eind_datum,t.eind_moment)>public.voorraad_daggrens(t.datum,t.moment);v:=t.totaal+r+c-t.eind_totaal-k;
INSERT INTO public.voorraad_periode(voorraad_artikel_id,begin_telling_id,eind_telling_id,begindatum,einddatum,begin,ontvangen,correcties,kassa,eind,onverklaard,pct_van_kassa,volledig) VALUES(a.id,t.id,t.eind_id,t.datum,t.eind_datum,t.totaal,r,c,k,t.eind_totaal,v,100*v/nullif(k,0),ok) ON CONFLICT(voorraad_artikel_id,begin_telling_id) DO UPDATE SET eind_telling_id=excluded.eind_telling_id,einddatum=excluded.einddatum,begin=excluded.begin,ontvangen=excluded.ontvangen,correcties=excluded.correcties,kassa=excluded.kassa,eind=excluded.eind,onverklaard=excluded.onverklaard,pct_van_kassa=excluded.pct_van_kassa,volledig=excluded.volledig,bijgewerkt_op=now();END LOOP;
SELECT count(*)n,sum(onverklaard)som,sum(kassa)kassa,max(abs(pct_van_kassa))max_pct INTO x FROM public.voorraad_periode WHERE voorraad_artikel_id=a.id AND volledig;
IF x.n>=3 AND x.kassa>0 THEN INSERT INTO public.leer_voorstel(vestiging,onderwerp,voorraad_artikel_id,soort,huidige_waarde,voorgestelde_waarde,onderbouwing) VALUES(a.vestiging,a.naam,a.id,'verbruiksopslag_pct',a.verbruiksopslag_pct,100*x.som/x.kassa,jsonb_build_object('periodes',x.n,'onverklaard',x.som,'kassa',x.kassa,'reden','Controleer ontvangst en dosering; niet automatisch toegepast')) ON CONFLICT(vestiging,onderwerp,soort) WHERE status='open' DO UPDATE SET voorgestelde_waarde=excluded.voorgestelde_waarde,onderbouwing=excluded.onderbouwing,bijgewerkt_op=now();END IF;
IF x.max_pct>30 THEN INSERT INTO public.leer_voorstel(vestiging,onderwerp,voorraad_artikel_id,soort,onderbouwing) VALUES(a.vestiging,a.naam,a.id,'onderzoeken',jsonb_build_object('max_pct',x.max_pct,'reden','Controleer koppeling, levering en dosering')) ON CONFLICT(vestiging,onderwerp,soort) WHERE status='open' DO UPDATE SET onderbouwing=excluded.onderbouwing,bijgewerkt_op=now();END IF;END LOOP;
FOR x IN SELECT * FROM public.v_advies_nauwkeurigheid WHERE n>=4 AND mape>25 LOOP INSERT INTO public.leer_voorstel(vestiging,onderwerp,artikel_id,soort,onderbouwing) VALUES(x.vestiging,x.artikel,x.artikel_id,'advies_controleren',jsonb_build_object('n',x.n,'mape',x.mape,'nulverbruik',x.nulverbruik,'reden','Controleer adviesmethode; nulverbruik buiten MAPE')) ON CONFLICT(vestiging,onderwerp,soort) WHERE status='open' DO UPDATE SET onderbouwing=excluded.onderbouwing,bijgewerkt_op=now();END LOOP;
RETURN jsonb_build_object('logs',(SELECT count(*) FROM public.advies_log),'periodes',(SELECT count(*) FROM public.voorraad_periode),'voorstellen',(SELECT count(*) FROM public.leer_voorstel WHERE status='open'));END $$;
REVOKE ALL ON FUNCTION public.leercurve_bijwerken() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.leercurve_bijwerken() TO service_role,postgres;
COMMENT ON FUNCTION public.bestelbot_advies_loggen(text,date,date,jsonb,text) IS 'Service-only atomische wrapper: ongewijzigde adviesvervanging en idempotent log; metadatafout rolt alles terug.';
COMMENT ON FUNCTION public.leercurve_bijwerken() IS 'Service/postgres-only dagelijks 02:45 UTC; alleen nieuwe logs/periodes/voorstellen schrijven. Periode [daggrens(begin),daggrens(eind)); ochtend >= datum/sluit > datum. Gemengde momenten onvolledig. Geen opslag toepassen.';
COMMENT ON VIEW public.v_advies_nauwkeurigheid IS 'security_invoker; MAPE=100*avg(abs(advies-later_verkocht)/abs(later_verkocht)); nulverbruik apart, geen deling door nul.';
COMMENT ON VIEW public.v_leer_voorstellen_open IS 'security_invoker; alleen open voorstellen eigen vestiging; nieuwste eerst; geen automatische actie.';